/**
 * 订单详情页逻辑
 * 功能：加载并展示订单详情，根据订单状态提供对应操作
 *       包含取消订单、确认送达、评价订单等交互
 * 数据来源：云数据库直读 + 云函数 rateOrder / completeOrder
 */

var app = getApp()
var commonUtil = require('../../utils/common-util.js')

Page({
  data: {
    // 订单ID（从页面参数传入）
    orderId: null,
    // 订单详情数据
    order: null,
    // 用户评分（1-5）
    rating: 0,
    // 评价内容
    ratingText: '',
    // 是否已评价
    isRated: false,
    // 是否正在提交
    submitting: false,
    // 状态标题文案
    statusText: '',
    // 状态描述文案
    statusDesc: '',
    // 发布时间格式化文本
    createTimeText: '',
    // 是否是订单发布者
    isOwner: false,
    // 是否是订单接单者
    isAcceptor: false,
    // 是否显示联系方式
    showContact: false,
    // 联系电话
    contactPhone: '',
    // 未读消息数
    unreadCount: 0,
    // 是否正在上传照片
    uploading: false,
    // 是否显示上传方式选择弹窗
    showUploadModal: false,
    // 证明提示文案（按分类）
    proofTipText: ''
  },

  /**
   * 页面加载
   * 从云数据库读取订单详情
   * @param {Object} options - 页面参数，包含订单id
   */
  onLoad: function (options) {
    var that = this
    var orderId = options.id
    if (!orderId) {
      wx.navigateBack()
      return
    }
    that.setData({ orderId: orderId, fromAdmin: options.from === 'admin' })
    wx.showLoading({ title: '加载中' })

    // 从云数据库读取单个订单（管理员通过云函数读取绕过权限）
    if (options.from === 'admin') {
      wx.cloud.callFunction({
        name: 'login',
        data: { action: 'getOrderDetail', _id: orderId },
        success: function (res) {
          if (res.result && res.result.code === 0) {
            that.processOrder(res.result.data)
          } else {
            wx.showToast({ title: '订单不存在', icon: 'none' })
          }
        },
        fail: function () { wx.showToast({ title: '加载失败', icon: 'none' }); wx.hideLoading() }
      })
      return
    }

    var db = wx.cloud.database()
    db.collection('orders').doc(orderId).get({
      success: function (res) {
        that.processOrder(res.data)
      },
      fail: function (err) {
        wx.showToast({ title: '获取订单失败', icon: 'none' })
        wx.hideLoading()
      }
    })
  },

  processOrder: function (order) {
    var that = this
    if (!order) return

    // 进入订单详情时，自动标记该订单的消息为已读（针对已接单/已送达状态）
    if (order.status === 'accepted' || order.status === 'delivered') {
      wx.cloud.callFunction({
        name: 'markMessagesRead',
        data: { orderId: that.data.orderId },
        fail: function () {}
      })
    }

    // 异步转换图片 fileID 为临时 URL（不阻塞UI）
    commonUtil.convertOrderImages([order]).then(function() {
      that.setData({ order: order })
    })

    var createTime = order.createTime
    var createTimeText = ''
    if (createTime) {
      var d = new Date(createTime)
      createTimeText = d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0') + ' ' +
        String(d.getHours()).padStart(2, '0') + ':' +
        String(d.getMinutes()).padStart(2, '0')
    }

    order.statusText = that.getStatusText(order.status)
    var isTimeout = false
    if (order.status === 'accepted' && order.acceptTime) {
      var acceptTime = new Date(order.acceptTime).getTime()
      if (Date.now() - acceptTime > 48 * 60 * 60 * 1000) {
        isTimeout = true
        order.statusText = '超时未完成'
      }
    }

    // 上传时间格式化
    if (order.uploadTime) {
      var ut = new Date(order.uploadTime)
      order.uploadTimeText = ut.getFullYear() + '-' +
        String(ut.getMonth() + 1).padStart(2, '0') + '-' +
        String(ut.getDate()).padStart(2, '0') + ' ' +
        String(ut.getHours()).padStart(2, '0') + ':' +
        String(ut.getMinutes()).padStart(2, '0')
    }

    that.setData({
      order: order,
      statusText: order.statusText,
      statusDesc: isTimeout ? '接单后超过48小时未完成，建议联系对方或取消接单' : that.getStatusDesc(order.status, order.cancelReason),
      createTimeText: createTimeText,
      isTimeout: isTimeout,
      isRated: !!order.rating,
      fromAdmin: that.data.fromAdmin
    })

    that.checkUserIdentity(order)
    that.loadPublisherInfo(order)
    wx.hideLoading()
  },

  loadPublisherInfo: function (order) {
    var that = this
    if (!order || !order.publisherId) return
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getUserInfo', openid: order.publisherId },
      success: function (res) {
        if (res.result && res.result.code === 0 && res.result.data) {
          var user = res.result.data
          that.setData({
            'order.publisherName': user.nickName || order.publisherName || '用户'
          })
        }
      },
      fail: function () {}
    })
  },

  /**
   * 检查当前用户身份
   * 判断是否是发布者/接单者，决定操作权限和联系方式显示
   */
  checkUserIdentity: function (order) {
    var that = this
    var cachedOpenId = wx.getStorageSync('myOpenId') || ''
    var cachedUserInfo = app.globalData && app.globalData.userInfo
    var myOpenId = cachedOpenId || (cachedUserInfo && cachedUserInfo._openid) || ''

    if (myOpenId) {
      that.applyUserIdentity(order, myOpenId)
    } else {
      wx.cloud.callFunction({
        name: 'login',
        data: { action: 'autoCreate', _id: (app.globalData.userInfo && app.globalData.userInfo._id) || '' },
        success: function (loginRes) {
          var loginData = loginRes.result.data
          if (loginData && loginData._openid) {
            wx.setStorageSync('myOpenId', loginData._openid)
            that.applyUserIdentity(order, loginData._openid)
          }
        },
        fail: function () {}
      })
    }
  },

  applyUserIdentity: function (order, openid) {
    var isOwner = order.publisherId === openid
    var isAcceptor = order.acceptorId === openid
    var showContact = false
    var contactPhone = ''

    if (order.status === 'accepted' || order.status === 'delivered' || order.status === 'paid') {
      showContact = true
      if (isOwner) {
        contactPhone = order.acceptorPhone || '未提供'
      } else if (isAcceptor) {
        contactPhone = order.publisherPhone || '未提供'
      } else {
        showContact = false
      }
    }

    this.setData({
      isOwner: isOwner,
      isAcceptor: isAcceptor,
      showContact: showContact,
      contactPhone: contactPhone
    })

    this.loadUnreadCount(this.data.orderId, openid)
  },

  /**
   * 获取状态对应的CSS class名
   * @param {string} status - 订单状态
   * @returns {string} CSS class名
   */
  getStatusClass: function (status) {
    var classMap = {
      'pending': 'pending',
      'accepted': 'accepted',
      'delivered': 'delivered',
      'paid': 'paid'
    }
    return classMap[status] || 'pending'
  },

  /**
   * 获取状态标题文案
   * @param {string} status - 订单状态
   * @returns {string} 状态标题
   */
  getStatusText: function (status) {
    var textMap = {
      'pending': '等待接单中...',
      'accepted': '搬运进行中',
      'delivered': '已送达，待付款',
      'paid': '交易完成',
      'cancelled': '订单已取消',
      'expired': '订单已过期'
    }
    return textMap[status] || '等待接单中...'
  },

  /**
   * 获取状态描述文案
   * @param {string} status - 订单状态
   * @returns {string} 状态描述
   */
  getStatusDesc: function (status, cancelReason) {
    var descMap = {
      'pending': '已发布需求，等待同学来帮忙',
      'accepted': '同学正在为你服务',
      'delivered': '任务已完成，请通过微信转账支付',
      'paid': '交易已完成，感谢使用帮到位',
      'cancelled': cancelReason || '订单已取消',
      'expired': '订单已过期'
    }
    return descMap[status] || '已发布需求，等待同学来帮忙'
  },

  /**
   * 点击星星设置评分
   * @param {Object} e - 事件对象，获取data-star值
   */
  onSelectStar: function (e) {
    var star = e.currentTarget.dataset.star
    this.setData({ rating: star })
  },

  /**
   * 评价内容输入
   * @param {Object} e - 输入事件
   */
  onRateInput: function (e) {
    this.setData({ ratingText: e.detail.value })
  },

  /**
   * 提交评价
   * 校验评分后调用云函数 rateOrder
   */
  onSubmitRate: function () {
    var that = this
    var orderId = that.data.orderId
    var rating = that.data.rating
    var ratingText = that.data.ratingText
    var submitting = that.data.submitting

    // 防止重复提交
    if (submitting) return

    // 校验评分
    if (rating === 0) {
      wx.showToast({
        title: '请选择评分',
        icon: 'none'
      })
      return
    }

    // 设置提交中状态
    that.setData({ submitting: true })

    // 调用云函数提交评价
    wx.cloud.callFunction({
      name: 'rateOrder',
      data: {
        orderId: orderId,
        score: rating,
        content: ratingText
      },
      success: function (res) {
        var result = res.result
        if (result.code === 0) {
          wx.showToast({
            title: '评价成功',
            icon: 'success'
          })
          // 更新订单评价状态
          that.setData({
            isRated: true,
            submitting: false,
            'order.rating': rating,
            'order.reviewContent': ratingText
          })
        } else {
          wx.showToast({
            title: result.msg || '评价失败',
            icon: 'none'
          })
          that.setData({ submitting: false })
        }
      },
      fail: function (err) {
        console.error('[帮到位] rateOrder云函数失败', err)
        wx.showToast({
          title: '评价失败，请重试',
          icon: 'none'
        })
        that.setData({ submitting: false })
      }
    })
  },

  /**
   * 取消订单
   * 发布者可以直接取消订单（任何状态，除了已完成）
   */
  onCancelOrder: function () {
    var that = this
    var order = that.data.order
    if (!order) return

    if (order.status === 'paid') {
      wx.showToast({ title: '订单已完成，无法取消', icon: 'none' })
      return
    }

    var content = '确定要取消这个订单吗？'
    if (order.status === 'accepted' || order.status === 'delivered') {
      content = '订单已被接单，确定要取消吗？取消后接单者将收到通知。'
    }

    wx.showModal({
      title: '取消订单',
      content: content,
      confirmColor: '#EF4444',
      confirmText: '确定取消',
      success: function (res) {
        if (res.confirm) {
          wx.cloud.callFunction({
            name: 'cancelOrder',
            data: { orderId: that.data.orderId },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({ title: '订单已取消', icon: 'success' })
                setTimeout(function () { wx.navigateBack() }, 1500)
              } else {
                wx.showToast({ title: result.msg || '取消失败', icon: 'none' })
              }
            },
            fail: function (err) {
              console.error('[帮到位] 取消订单失败', err)
              wx.showToast({ title: '取消失败，请重试', icon: 'none' })
            }
          })
        }
      }
    })
  },

  /**
   * 修改信息
   * 跳转到发布页进行修改（编辑模式）
   */
  onEditOrder: function () {
    var that = this
    var order = that.data.order
    if (!order) return
    // tabBar页面不能用navigateTo，改用缓存+switchTab
    wx.setStorageSync('editOrder', JSON.stringify({
      id: that.data.orderId,
      building: order.building || '',
      floor: order.floor ? String(order.floor) : '',
      room: order.room || '',
      phone: order.publisherPhone || '',
      count: order.count || 1,
      price: order.price ? String(order.price) : '',
      remark: order.remark || '',
      deliveryTime: order.deliveryTime || ''
    }))
    wx.switchTab({
      url: '/pages/publish/publish'
    })
  },

  /**
   * 获取证明提示文案（按分类）
   */
  getProofTipText: function (category) {
    var tipMap = {
      water: '请上传送达照片证明（水桶放在门口/宿舍的照片），图片将自动记录时间水印',
      errand: '请上传完成证明（物品送达照片或聊天记录截图），图片将自动记录时间水印',
      substitute: '请上传教室证明（教室照片或签到截图），图片将自动记录时间水印',
      secondhand: '请上传物品交付证明（交易照片或聊天记录截图），图片将自动记录时间水印',
      other: '请上传完成证明（现场照片或聊天记录截图），图片将自动记录时间水印'
    }
    return tipMap[category] || '请上传完成证明，图片将自动记录时间水印'
  },

  /**
   * 点击上传证明（弹出选择方式）
   */
  onPhotoComplete: function () {
    var that = this
    var category = that.data.order && that.data.order.category || 'other'
    that.setData({
      showUploadModal: true,
      proofTipText: that.getProofTipText(category)
    })
  },

  /**
   * 关闭上传方式弹窗
   */
  closeUploadModal: function () {
    this.setData({ showUploadModal: false })
  },

  /**
   * 选择拍照方式
   */
  chooseCamera: function () {
    var that = this
    that.setData({ showUploadModal: false })
    that.doUploadPhoto('camera')
  },

  /**
   * 选择相册方式
   */
  chooseAlbum: function () {
    var that = this
    that.setData({ showUploadModal: false })
    that.doUploadPhoto('album')
  },

  /**
   * 执行上传照片（拍照或相册）
   * 优化：直接用 Canvas 一步完成缩放 + 水印，速度更快
   */
  doUploadPhoto: function (sourceType) {
    var that = this
    wx.chooseImage({
      count: 1,
      sizeType: ['compressed'],
      sourceType: [sourceType],
      success: function (res) {
        var tempFilePath = res.tempFilePaths[0]
        that.setData({ uploading: true })
        // 一步完成：缩放 + 水印（最大边1200px，质量70，约100KB以内）
        that.processAndWatermark(tempFilePath, 1200, 0.7).then(function(finalPath) {
          wx.cloud.uploadFile({
            cloudPath: 'delivery-photos/' + that.data.orderId + '_' + Date.now() + '.jpg',
            filePath: finalPath,
            success: function (uploadRes) {
              wx.cloud.callFunction({
                name: 'completeOrder',
                data: {
                  orderId: that.data.orderId,
                  photoUrl: uploadRes.fileID,
                  uploadType: sourceType,
                  uploadTime: Date.now()
                },
                success: function (res) {
                  var result = res.result
                  if (result.code === 0) {
                    wx.showToast({ title: '送达完成', icon: 'success' })
                    that.reloadOrder()
                  } else {
                    wx.showToast({ title: result.msg || '操作失败', icon: 'none' })
                  }
                },
                fail: function () {
                  wx.showToast({ title: '操作失败', icon: 'none' })
                },
                complete: function () { that.setData({ uploading: false }) }
              })
            },
            fail: function () {
              wx.showToast({ title: '照片上传失败', icon: 'none' })
              that.setData({ uploading: false })
            }
          })
        }).catch(function() {
          // 处理失败，直接上传原图（微信已压缩过）
          wx.cloud.uploadFile({
            cloudPath: 'delivery-photos/' + that.data.orderId + '_' + Date.now() + '.jpg',
            filePath: tempFilePath,
            success: function (uploadRes) {
              wx.cloud.callFunction({
                name: 'completeOrder',
                data: {
                  orderId: that.data.orderId,
                  photoUrl: uploadRes.fileID,
                  uploadType: sourceType,
                  uploadTime: Date.now()
                },
                success: function (res) {
                  var result = res.result
                  if (result.code === 0) {
                    wx.showToast({ title: '送达完成', icon: 'success' })
                    that.reloadOrder()
                  } else {
                    wx.showToast({ title: result.msg || '操作失败', icon: 'none' })
                  }
                },
                fail: function () { wx.showToast({ title: '操作失败', icon: 'none' }) },
                complete: function () { that.setData({ uploading: false }) }
              })
            },
            fail: function () {
              wx.showToast({ title: '照片上传失败', icon: 'none' })
              that.setData({ uploading: false })
            }
          })
        })
      }
    })
  },

  /**
   * 一步完成：图片缩放 + 时间水印
   * 比先压缩再加水印快很多，只需要一次 Canvas 操作
   * @param {String} filePath - 原图路径
   * @param {Number} maxEdge - 最大边像素（默认1200）
   * @param {Number} quality - 导出质量 0-1（默认0.7）
   */
  processAndWatermark: function (filePath, maxEdge, quality) {
    var that = this
    maxEdge = maxEdge || 1200
    quality = quality || 0.7
    return new Promise(function(resolve, reject) {
      wx.getImageInfo({
        src: filePath,
        success: function (imgInfo) {
          var query = wx.createSelectorQuery()
          query.select('#watermarkCanvas')
          query.fields({ node: true, size: true })
          query.exec(function (res) {
            if (!res || !res[0] || !res[0].node) {
              reject(new Error('canvas not found'))
              return
            }
            var canvas = res[0].node
            var ctx = canvas.getContext('2d')

            // 计算缩放后尺寸
            var width = imgInfo.width
            var height = imgInfo.height
            if (width > maxEdge || height > maxEdge) {
              if (width >= height) {
                height = Math.round(height * maxEdge / width)
                width = maxEdge
              } else {
                width = Math.round(width * maxEdge / height)
                height = maxEdge
              }
            }

            canvas.width = width
            canvas.height = height

            // 绘制原图（已缩放）
            var img = canvas.createImage()
            img.onload = function () {
              ctx.drawImage(img, 0, 0, width, height)

              // 绘制时间水印（左上角）
              var now = new Date()
              var timeText = now.getFullYear() + '-' +
                String(now.getMonth() + 1).padStart(2, '0') + '-' +
                String(now.getDate()).padStart(2, '0') + ' ' +
                String(now.getHours()).padStart(2, '0') + ':' +
                String(now.getMinutes()).padStart(2, '0')

              var fontSize = Math.max(14, Math.floor(width * 0.035))
              ctx.font = fontSize + 'px sans-serif'
              ctx.textBaseline = 'top'

              var textWidth = ctx.measureText(timeText).width
              var padding = fontSize * 0.4
              var bgWidth = textWidth + padding * 2
              var bgHeight = fontSize + padding * 2
              var marginX = Math.floor(width * 0.025)
              var marginY = Math.floor(height * 0.025)

              ctx.fillStyle = 'rgba(0, 0, 0, 0.6)'
              ctx.fillRect(marginX, marginY, bgWidth, bgHeight)

              ctx.fillStyle = '#ffffff'
              ctx.fillText(timeText, marginX + padding, marginY + padding)

              // 导出图片
              wx.canvasToTempFilePath({
                canvas: canvas,
                x: 0,
                y: 0,
                width: width,
                height: height,
                destWidth: width,
                destHeight: height,
                fileType: 'jpg',
                quality: quality,
                success: function (tempRes) {
                  resolve(tempRes.tempFilePath)
                },
                fail: function () {
                  reject(new Error('export failed'))
                }
              })
            }
            img.onerror = function () {
              reject(new Error('image load failed'))
            }
            img.src = filePath
          })
        },
        fail: function () {
          reject(new Error('getImageInfo failed'))
        }
      })
    })
  },

  /**
   * 确认付款
   * 发布者确认已通过微信转账支付
   */
  onConfirmPayment: function () {
    var that = this
    var orderId = that.data.orderId

    wx.showModal({
      title: '确认付款',
      content: '确认已通过微信转账支付报酬给接单人了吗？',
      confirmColor: '#0EA5E9',
      success: function (res) {
        if (res.confirm) {
          wx.cloud.callFunction({
            name: 'confirmPayment',
            data: {
              orderId: orderId
            },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({
                  title: '已确认付款',
                  icon: 'success'
                })
                // 重新从数据库读取最新的订单数据
                that.reloadOrder()
              } else {
                wx.showToast({
                  title: result.msg || '操作失败',
                  icon: 'none'
                })
              }
            },
            fail: function (err) {
              console.error('[帮到位] confirmPayment云函数失败', err)
              wx.showToast({
                title: '操作失败，请重试',
                icon: 'none'
              })
            }
          })
        }
      }
    })
  },

  /**
   * 接单者确认收款
   */
  onConfirmReceived: function () {
    var that = this
    wx.showModal({
      title: '确认收款',
      content: '确认已收到微信转账 ¥' + (that.data.order.price || 0) + '？',
      confirmColor: '#0EA5E9',
      success: function (res) {
        if (res.confirm) {
          wx.cloud.callFunction({
            name: 'confirmReceived',
            data: { orderId: that.data.orderId },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({ title: '已确认收款', icon: 'success' })
                that.reloadOrder()
              } else {
                wx.showToast({ title: result.msg || '操作失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '操作失败，请重试', icon: 'none' })
            }
          })
        }
      }
    })
  },

  /**
   * 接单者取消接单（订单回到pending状态，重新出现在待接单列表）
   */
  onCancelAccept: function () {
    var that = this
    wx.showModal({
      title: '取消接单',
      content: '请填写取消接单的理由（发布者将收到通知）',
      editable: true,
      placeholderText: '请输入取消理由',
      confirmColor: '#EF4444',
      confirmText: '确定取消',
      success: function (res) {
        if (res.confirm) {
          var reason = res.content || ''
          if (!reason.trim()) {
            wx.showToast({ title: '请填写取消理由', icon: 'none' })
            return
          }
          wx.cloud.callFunction({
            name: 'cancelAccept',
            data: { orderId: that.data.orderId, reason: reason.trim() },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({ title: '已取消接单', icon: 'success' })
                setTimeout(function () { wx.navigateBack() }, 1500)
              } else {
                wx.showToast({ title: result.msg || '取消失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '操作失败', icon: 'none' })
            }
          })
        }
      }
    })
  },

  /**
   * 投诉
   * 弹出投诉选项，支持预设原因和自定义输入
   */
  onComplain: function () {
    var that = this
    var orderId = that.data.orderId

    wx.showActionSheet({
      itemList: ['手机号码虚假', '对方爽约/未出现', '服务态度差', '其他问题'],
      itemColor: '#333333',
      success: function (res) {
        var tapIndex = res.tapIndex
        var reasonMap = {
          0: '手机号码虚假',
          1: '对方爽约/未出现',
          2: '服务态度差'
        }

        if (tapIndex === 3) {
          // 其他问题 - 弹出输入框让用户自定义填写
          wx.showModal({
            title: '投诉',
            content: '请描述遇到的问题（建议通过聊天沟通解决）',
            confirmText: '我要投诉',
            confirmColor: '#EF4444',
            editable: true,
            placeholderText: '请输入投诉原因',
            success: function (modalRes) {
              if (modalRes.confirm) {
                var reason = modalRes.content || '其他问题'
                that.submitComplain(orderId, reason)
              }
            }
          })
        } else {
          // 预设原因 - 直接提交
          var reason = reasonMap[tapIndex] || '未知原因'
          that.submitComplain(orderId, reason)
        }
      }
    })
  },

  /**
   * 提交投诉到云函数
   */
  submitComplain: function (orderId, reason) {
    wx.cloud.callFunction({
      name: 'complainOrder',
      data: {
        orderId: orderId,
        reason: reason
      },
      success: function (res) {
        var result = res.result
        if (result.code === 0) {
          wx.showToast({
            title: '投诉已提交',
            icon: 'success'
          })
        } else {
          wx.showToast({
            title: result.msg || '投诉失败',
            icon: 'none'
          })
        }
      },
      fail: function (err) {
        console.error('[帮到位] complainOrder云函数失败', err)
        wx.showToast({
          title: '投诉失败，请重试',
          icon: 'none'
        })
      }
    })
  },

  /**
   * 拨打对方电话
   */
  onCallPorter: function () {
    var contactPhone = this.data.contactPhone
    if (!contactPhone || contactPhone === '未提供') {
      wx.showToast({ title: '暂无联系方式', icon: 'none' })
      return
    }
    wx.makePhoneCall({
      phoneNumber: contactPhone
    })
  },

  /**
   * 联系接单人
   * 使用微信拨打电话功能
   */
  onContact: function () {
    var order = this.data.order
    if (!order) return

    // 显示接单者联系方式
    var phone = order.acceptorPhone || '未提供'
    wx.showModal({
      title: '联系方式',
      content: '接单人电话：' + phone,
      showCancel: false,
      confirmText: '知道了'
    })

    // 如果有真实手机号，也可以直接拨打：
    // if (order.acceptorPhone) {
    //   wx.makePhoneCall({ phoneNumber: order.acceptorPhone })
    // }
  },

  /**
   * 重新从数据库加载订单数据
   */
  reloadOrder: function () {
    var that = this
    var db = wx.cloud.database()
    db.collection('orders').doc(that.data.orderId).get({
      success: function (detailRes) {
        var order = detailRes.data

        // 格式化 createTime
        var createTime = order.createTime
        var createTimeText = ''
        if (createTime) {
          var d = new Date(createTime)
          createTimeText = d.getFullYear() + '-' +
            String(d.getMonth() + 1).padStart(2, '0') + '-' +
            String(d.getDate()).padStart(2, '0') + ' ' +
            String(d.getHours()).padStart(2, '0') + ':' +
            String(d.getMinutes()).padStart(2, '0')
        }

        that.setData({
          order: order,
          statusText: that.getStatusText(order.status),
          statusDesc: that.getStatusDesc(order.status, order.cancelReason),
          createTimeText: createTimeText,
          isRated: false,
          rating: 0,
          ratingText: ''
        })

        // 重新检查用户身份和联系方式
        that.checkUserIdentity(order)
      }
    })
  },

  /**
   * 接单操作（从订单详情页接单）
   */
  onAcceptOrder: function () {
    var that = this
    var orderId = that.data.orderId

    // 检查登录状态
    if (!getApp().checkLoginAndProfile()) return

    wx.showModal({
      title: '确认接单',
      content: '确认接下这个订单吗？',
      confirmColor: '#0EA5E9',
      success: function (res) {
        if (res.confirm) {
          wx.cloud.callFunction({
            name: 'acceptOrder',
            data: { orderId: orderId },
            success: function (acceptRes) {
              var result = acceptRes.result
              if (result.code === 0) {
                wx.showToast({ title: '接单成功', icon: 'success' })
                that.reloadOrder()
              } else {
                wx.showToast({ title: result.msg || '接单失败', icon: 'none' })
              }
            },
            fail: function (err) {
              console.error('[帮到位] 接单云函数失败', err)
              wx.showToast({ title: '接单失败，请重试', icon: 'none' })
            }
          })
        }
      }
    })
  },

  /**
   * 预览商品图片
   */
  previewProductImages: function (e) {
    var url = e.currentTarget.dataset.url
    var images = this.data.order.productImages
    if (images && images.length > 0) {
      wx.previewImage({ urls: images, current: url || images[0] })
    }
  },

  /**
   * 预览送达照片
   */
  previewDeliveryPhoto: function () {
    var photo = this.data.order.deliveryPhoto
    if (photo) {
      wx.previewImage({ urls: [photo], current: photo })
    }
  },

  /**
   * 复制订单编号
   */
  onCopyOrderNo: function () {
    var order = this.data.order
    if (order && order.orderNo) {
      wx.setClipboardData({
        data: order.orderNo,
        success: function () {
          wx.showToast({ title: '已复制订单编号', icon: 'success' })
        }
      })
    }
  },

  /**
   * 发布人和接单人之间的沟通
   */
  goChat: function () {
    var order = this.data.order
    if (!order) return
    var orderId = this.data.orderId
    var orderNo = order.orderNo || ''

    // 通过云函数标记消息为已读
    wx.cloud.callFunction({
      name: 'markMessagesRead',
      data: { orderId: orderId },
      fail: function () {}
    })

    wx.navigateTo({
      url: '/pages/chat/chat?id=' + orderId + '&orderNo=' + orderNo
    })
  },

  /**
   * 查询未读消息数
   */
  loadUnreadCount: function (orderId, myOpenId) {
    var that = this
    if (!myOpenId || !orderId) return
    var db = wx.cloud.database()
    db.collection('messages').where({
      orderId: orderId,
      senderId: db.command.neq(myOpenId),
      isRead: db.command.neq(true)
    }).count({
      success: function (res) {
        that.setData({ unreadCount: res.total })
      },
      fail: function () {}
    })
  },

  /**
   * 分享给好友（订单完成后）
   */
  onShareAppMessage: function () {
    var order = this.data.order
    var title = '帮到位 - 校园万能互助平台'
    if (order) {
      title = order.building + '栋' + order.floor + '楼 需要帮忙，快来接单吧！'
    }
    return {
      title: title,
      path: '/pages/index/index',
      imageUrl: ''
    }
  },

  /**
   * 手动触发分享
   */
  onShareToFriend: function () {
    // 使用 button 的 open-type="share" 触发
  }
})
